import { useState } from "react";
import { useNavigate }  from "react-router-dom";

export default function CreateReport() {
    // Key report information from input fields NOT including things like ID, date, or confirmedCount which will be generated by the backend 
    const [formData, setFormData] = useState({title: '', description: '', lineNumber: '', lineStation: ''});
    const navigate = useNavigate(); // Used to navigate to the live feed page after successful submission of the report

    const handleSubmit = (e) => {
        e.preventDefault();
        try {
            // RELPLACE WITH ACTUAL BACKEND IMPLEMENTATION
            window.parent.postMessage(JSON.stringify(formData), '*');
            console.log("Sending Report: ", JSON.stringify(formData));
            alert("Successfully submitted report!");
            navigate("/live-feed");
        } catch (error) {
            alert("Something went wrong.");
        }
    }

    // TODO: Actuall call API for lines and stations to fill dropdown options 

    return (
        <div>
            <br></br>

            <div className="card" style={{ width: 'fit-content', margin: 'auto' }}>
                <h2>Create Report</h2>
                <hr></hr>

                <form onSubmit={handleSubmit}>
                    {/* The report title */}
                    <label htmlFor="title"><h3>Title</h3></label>
                    <input style={{ width: '50vw' }} type="text" id="title" name="title" placeholder="Enter a title for your report" required value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })}/>

                    {/* The line number and station (text) where the issue is happening. Value IS the lineNumber as well*/}
                    <label htmlFor="line"><h3>Line</h3></label>
                    <select style={{ width: '52vw' }} id="line" name="line" required value={formData.line} onChange={(e) => setFormData({...formData, lineNumber: e.target.value})}>
                        <option value="">Select a line</option>
                        <option value="1">Line 1</option>
                        <option value="2">Line 2</option>
                        <option value="4">Line 4</option>
                        <option value="5">Line 5</option>
                        <option value="6">Line 6</option>
                    </select>

                    {/* The station where the issue is happening. Value IS the lineStation as well*/}
                    <label htmlFor="station"><h3>Station</h3></label>
                    <select style={{ width: '52vw' }} id="station" name="station" required value={formData.station} onChange={(e) => setFormData({...formData, lineStation: e.target.value})}>
                        <option value="">Select a station</option>
                        <option value="Station 1">Station 1</option>
                        <option value="Station 2">Station 2</option>
                        <option value="Station 4">Station 4</option>
                        <option value="Station 5">Station 5</option>
                        <option value="Station 6">Station 6</option>
                    </select>

                    {/* The description of the issue with common descriptions for easy populating*/}
                    <label htmlFor="description"><h3>What happened?</h3></label>
                    <textarea style={{ width: '50vw' }} id="description" name="description" placeholder="Describe the issue" required value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })}></textarea>
                    <button 
                        type="button"
                        className="btn secondary" 
                        style={{ display: 'block', margin: '16px auto', width: '50vw' }} 
                        onClick={() => setFormData({ ...formData, description: "Common issue #1" })}>
                        Common issue #1
                    </button>
                    <button 
                        type="button"
                        className="btn secondary" 
                        style={{ display: 'block', margin: '16px auto', width: '50vw' }} 
                        onClick={() => setFormData({ ...formData, description: "Common issue #2" })}>
                        Common issue #2
                    </button>
                    <button
                        type="button"
                        className="btn secondary"
                        style={{ display: 'block', margin: '16px auto', width: '50vw' }}
                        onClick={() => setFormData({ ...formData, description: "Common issue #3" })}>
                        Common issue #3
                    </button>
                    
                    <hr ></hr>

                    <button className="btn primary" style={{ display: 'block', margin: '16px auto', width: '50vw' }}>Submit Report</button>
                </form>
                {/* Simple cancel button that takes the user back to the live feed page without submitting a report */}
                <a href="/live-feed"><button className="btn secondary" style={{ display: 'block', margin: '16px auto', width: '50vw' }}>Cancel</button></a>
            </div>

            {/* Disclaimer about the type of information that should be included in a report */}
            <p style={{ margin: '16px auto', width: 'fit-content' }}>Share accurate and respectful updates. Do not include personal information.</p>
        </div>
    );
}